import json

class ImportProblem(Exception):
    def __init__(self, line):
        self.line = line
        super().__init__(f'invalid line {line}')

def _parse(raw):
    record = json.loads(raw.decode('utf-8'))
    if not isinstance(record, dict):
        raise ValueError()
    if not isinstance(record.get('id'), str) or not record['id']:
        raise ValueError()
    count = record.get('count')
    if not isinstance(count, int) or isinstance(count, bool):
        raise ValueError()
    return record

def import_bytes(payload, store):
    # Validate everything before touching the store so a bad line leaves it
    # unchanged. Physical lines are split on LF only (CRLF leaves a trailing
    # CR, which is JSON whitespace); bytes.splitlines would also split on a
    # lone CR and shift the reported line numbers.
    records = []
    for line, raw in enumerate(payload.split(b'\n'), 1):
        if not raw.strip(b' \t\r'):
            continue
        try:
            records.append(_parse(raw))
        except (UnicodeDecodeError, ValueError, RecursionError):
            raise ImportProblem(line) from None
    for record in records:
        store.append(record)
    return len(records)

